-- Re-runnable knowledge-base migration: moves the former Python rule catalogue
-- into reviewed Oracle RAG runbooks. Run after 02_seed_error_knowledge.sql.
MERGE INTO error_knowledge target
USING (
    SELECT 'Network' technology, 'TIMEOUT' error_code, 'Timeout or slow downstream dependency' title, 'A network call or operation exceeded its configured wait time.' description, 'Slow or unavailable downstream service, unsuitable timeout, or retry amplification.' likely_causes, 'Check the dependency health and latency. Correlate the timeout with request duration, then adjust timeouts and bounded retries.' remediation, 'Confirm the dependency responds within the agreed latency budget.' verification, 'timeout|timed out|readtimeout|sockettimeout' terms FROM dual
    UNION ALL SELECT 'Network', 'DNS_FAILURE', 'DNS resolution failure', 'The application could not resolve a host name.', 'Typo, missing service-discovery record, DNS outage, or incorrect network configuration.', 'Verify the hostname, DNS resolver configuration, service-discovery record, and name resolution from the application network.', 'Resolve the hostname from the runtime environment and retry the request.', 'unknownhostexception|name or service not known|getaddrinfo failed' FROM dual
    UNION ALL SELECT 'Network', 'TLS_FAILURE', 'TLS or certificate validation failure', 'A secure connection could not be established or verified.', 'Expired certificate, untrusted CA, hostname mismatch, or incompatible TLS configuration.', 'Inspect certificate expiry and subject/SAN, trust store, hostname, and enabled TLS versions. Do not disable validation as a permanent fix.', 'Complete a TLS handshake using the intended hostname and trusted CA.', 'sslexception|sslerror|certificate_verify_failed|certificate expired' FROM dual
    UNION ALL SELECT 'Network', 'PORT_IN_USE', 'Port already in use', 'Another process is already listening on the configured network port.', 'Duplicate service instance, stale process, or conflicting local configuration.', 'Identify the process using the port, stop it only if safe, or select a dedicated application port.', 'Start the service and confirm it binds only to the intended port.', 'address already in use|bindexception' FROM dual
    UNION ALL SELECT 'HTTP/API', 'HTTP_403', 'Authorization failure', 'The caller is authenticated but lacks permission for the requested resource.', 'Missing role, scope, policy binding, or resource-level permission.', 'Compare the caller identity and scopes with the endpoint policy; grant the minimum missing permission.', 'Repeat the request with the approved role or scope and confirm a successful response.', 'forbidden|http 403| 403 |access denied' FROM dual
    UNION ALL SELECT 'HTTP/API', 'HTTP_404', 'Resource not found', 'The requested endpoint, file, or resource could not be located.', 'Incorrect path, resource identifier, deployment version, or routing rule.', 'Validate the URL or path, deployment version, route mapping, and resource identifier.', 'Retrieve the expected resource using the same environment and request path.', 'not found|http 404| 404 ' FROM dual
    UNION ALL SELECT 'JVM/Python', 'MEMORY_EXHAUSTION', 'Memory exhaustion', 'The process ran out of available heap or process memory.', 'Memory leak, excessive retained data, unbounded concurrency, or undersized memory allocation.', 'Inspect heap/process memory, retained objects, request size, and concurrency. Fix retention or workload causes before increasing limits.', 'Run the representative workload without sustained memory growth or allocation failure.', 'outofmemory|out of memory|memoryerror' FROM dual
    UNION ALL SELECT 'JVM/Python', 'RECURSION_LIMIT', 'Stack overflow or recursion limit', 'An operation recursed too deeply, commonly through a circular call path.', 'Missing base condition, cyclic graph traversal, or recursive serialization.', 'Use the first repeating application frame to locate the cycle. Add a terminating condition or use an iterative traversal.', 'Exercise the cyclic and boundary cases without recursion failure.', 'stackoverflowerror|maximum recursion depth exceeded' FROM dual
    UNION ALL SELECT 'Database', 'DEADLOCK', 'Database deadlock', 'Concurrent transactions blocked each other in a cycle.', 'Inconsistent lock order or transactions holding locks for too long.', 'Identify the participating transactions, make lock acquisition order consistent, and keep transactions short. Retry only idempotent work.', 'Re-run concurrent transactions without deadlock and review lock waits.', 'deadlock' FROM dual
    UNION ALL SELECT 'Database', 'GENERIC_SQL_EXCEPTION', 'Database exception', 'The application received a database exception that needs its vendor code and SQL context.', 'Constraint, connectivity, syntax, schema, or migration problem.', 'Capture the complete vendor error, SQLSTATE/error code, SQL statement identifier, active schema, and recent migrations before changing data.', 'Reproduce with the same schema and confirm the vendor-specific runbook applies.', 'sqlexception|psqlexception|integrity constraint' FROM dual
    UNION ALL SELECT 'Java/JVM', 'MISSING_CLASS', 'Missing class or dependency', 'A required class or library is unavailable at runtime.', 'Missing JAR, incorrect classpath, shaded dependency issue, or incomplete deployment artifact.', 'Compare the build dependency tree with the deployed artifact and runtime classpath; pin compatible versions.', 'Load the class in the deployed runtime and run the affected request.', 'classnotfoundexception|noclassdeffounderror' FROM dual
    UNION ALL SELECT 'Java/JVM', 'INCOMPATIBLE_LIBRARY', 'Incompatible library version', 'A method expected by the application is missing at runtime.', 'Conflicting transitive dependencies or deployment built with a different library version.', 'Inspect dependency resolution and the deployed JARs; align and pin compatible versions, then rebuild.', 'Start the application and exercise the affected method without linkage errors.', 'nosuchmethoderror|abstractmethoderror' FROM dual
    UNION ALL SELECT 'Python/Java', 'INVALID_ARGUMENT', 'Invalid argument or input', 'A method received a value outside its accepted format or range.', 'Invalid caller input, contract drift, or missing boundary validation.', 'Use the first application stack frame to validate type, format, and range; return a controlled validation error where appropriate.', 'Add a boundary-case test and verify the controlled outcome.', 'illegalargumentexception|valueerror' FROM dual
    UNION ALL SELECT 'Python', 'INDEX_ERROR', 'Index out of range', 'Code accessed a sequence position that does not exist.', 'Empty or shorter-than-expected collection, off-by-one loop, or changed upstream payload.', 'Inspect collection length and loop boundaries before indexing; handle empty input intentionally.', 'Add empty and boundary collection tests.', 'indexerror|list index out of range' FROM dual
    UNION ALL SELECT 'Python', 'FILE_NOT_FOUND', 'File or directory not found', 'The application cannot locate a required file or directory.', 'Wrong relative path, working directory, packaging, mount, or deployment artifact.', 'Verify the resolved path, working directory, deployment package, mount, and read permission.', 'Resolve and read the required file from the deployed runtime.', 'filenotfounderror|no such file or directory' FROM dual
    UNION ALL SELECT 'Python', 'PERMISSION_DENIED', 'Permission denied', 'The process lacks access to a file, folder, or resource.', 'Incorrect ownership, ACL, service account, container mount, or cloud IAM policy.', 'Check the effective service identity and grant the minimum required filesystem or resource permission.', 'Repeat the action as the runtime identity and confirm access.', 'permissionerror|permission denied' FROM dual
    UNION ALL SELECT 'Python', 'DIVISION_BY_ZERO', 'Division by zero', 'A calculation attempted to divide by a zero value.', 'Unexpected zero input, missing aggregation data, or unvalidated denominator.', 'Validate the denominator and define the intended zero-case behaviour before calculating.', 'Add a zero-denominator test with the intended outcome.', 'zerodivisionerror|division by zero' FROM dual
    UNION ALL SELECT 'Python', 'SYNTAX_ERROR', 'Python syntax or indentation error', 'Python could not parse the source file.', 'Invalid syntax, indentation, merge conflict, or interpreter-version incompatibility.', 'Open the reported file and line, fix syntax/indentation, and run the project with the supported Python version.', 'Compile the module and execute its focused test.', 'syntaxerror|indentationerror' FROM dual
    UNION ALL SELECT 'Database', 'FOREIGN_KEY', 'Foreign-key violation', 'A write references a missing parent record or attempts an invalid delete.', 'Incorrect write order, missing parent data, or unsuitable cascade/delete behaviour.', 'Use the constraint and key values from the error to locate the parent/child rows; correct write order or data lifecycle.', 'Repeat the transaction and verify referential integrity.', 'foreign key constraint|foreignkeyviolation' FROM dual
    UNION ALL SELECT 'Database', 'TABLE_NOT_FOUND', 'Database table not found', 'The query targets a table or view missing from the active database or schema.', 'Missing migration, wrong schema, invalid synonym, or wrong connection target.', 'Verify active schema, migration status, quoted identifier spelling, synonym, and database target.', 'Resolve the object with the runtime account and rerun the query.', 'relation does not exist|table does not exist|invalid object name' FROM dual
    UNION ALL SELECT 'Database', 'COLUMN_NOT_FOUND', 'Database column not found', 'The query references a column absent from the target schema.', 'Application/database version mismatch, incomplete migration, or incorrect column name.', 'Inspect the deployed schema and migration version; align the query and application release.', 'Run the query against the target schema with the expected column present.', 'column does not exist|unknown column|invalid column name' FROM dual
    UNION ALL SELECT 'Database', 'SQL_SYNTAX', 'SQL syntax error', 'The database could not parse the SQL statement.', 'Malformed generated SQL, dialect mismatch, reserved identifier, or incorrect parameter substitution.', 'Review SQL near the reported position and use parameterized statements; validate the SQL dialect for the target engine.', 'Execute the corrected statement with representative parameters.', 'syntax error at or near|you have an error in your sql syntax' FROM dual
    UNION ALL SELECT 'Database', 'POOL_EXHAUSTED', 'Database connection pool exhausted', 'All pool connections are busy or the server connection limit was reached.', 'Leaked connections, slow queries, traffic burst, or unsuitable pool configuration.', 'Find unclosed connections and slow queries, then tune pool limits within database capacity.', 'Sustain representative load without pool wait or connection-limit errors.', 'too many connections|remaining connection slots|connection pool exhaust' FROM dual
    UNION ALL SELECT 'Database', 'LOCK_WAIT', 'Database lock wait timeout', 'A transaction waited too long for a lock.', 'Long transaction, blocking session, or inconsistent lock order.', 'Identify the blocker, shorten transaction scope, make lock order consistent, and retry only safe/idempotent work.', 'Re-run the workload without lock wait timeout.', 'lock wait timeout|could not obtain lock' FROM dual
) source
ON (target.technology = source.technology AND target.error_code = source.error_code)
WHEN MATCHED THEN UPDATE SET target.title = source.title, target.description = source.description,
    target.likely_causes = source.likely_causes, target.remediation = source.remediation,
    target.verification = source.verification, target.match_terms = source.terms, target.updated_at = SYSTIMESTAMP
WHEN NOT MATCHED THEN INSERT (technology, error_code, title, description, likely_causes, remediation, verification, match_terms)
VALUES (source.technology, source.error_code, source.title, source.description, source.likely_causes, source.remediation, source.verification, source.terms);

COMMIT;
